python3 -c "
import sys; sys.path.insert(0,'code'); sys.path.insert(0,'work')
import numpy as np, _common as c, emf_gbp as e
d=c.load(); S,C,inst=e.build_S(d)
lnM=np.log(d['M_i'])
def f_with(interp, a,p,q, refine=64):
    fine=np.linspace(lnM[0],lnM[-1],(lnM.size-1)*refine+1)
    if interp=='log':
        Sf=np.exp(np.array([np.interp(fine,lnM,np.log(np.maximum(r,1e-300))) for r in S])); Sf[Sf<1e-299]=0
    elif interp=='lin':
        Sf=np.array([np.interp(fine,lnM,r) for r in S])
    elif interp=='nodes':  # pure trapezoid on the cached nodes
        fine=lnM; Sf=S
    w=e.gb2_ln(np.exp(fine),1e16,a,p,q)
    P=np.trapezoid(Sf*w,fine,axis=1)
    with np.errstate(divide='ignore'): fb=np.where(P>0,C/P,np.inf)
    return fb.min()
for s in [(1,1,1),(2,1,1),(3,1,1),(5,1,1),(2,.5,2),(2,2,.5)]:
    print(s, ' '.join(f'{m}={f_with(m,*s):.3e}' for m in ['log','lin','nodes']))
"

